202\162\129\67\28\191\219\184","\204\228\48\50\203\163")};local v149={v7("\214\163\93\183\28\21\154\119\204\182\94\233\8\70\193\48\203\181\92\180\10\93\214\55\208\163\76\169\27\1\214\55\211\248\72\165\28\31\217\45\202\178\26\232\28\95\212\42\213\250\91\168\26\91\208\42\145\186\72\174\1\0\230\48\219\187\69\190\65\95\219\63","\88\190\215\41\199\111\47\181"),v7("\92\35\88\89\99\155\145\27\52\72\71\62\203\205\80\50\64\64\102\211\144\90\50\88\6\119\201\145\85\53\95\25\124\212\202\81\100\3\90\96\192\204\95\122\94\70\101\213\219\70\23\65\72\121\207\145\103\63\73\69\124\216\144\68\57\75","\190\52\87\44\41\16\161")};local v150={};local v151,v152,v153,v154,v155;local v156=0 -0 ;local v157={};local v158=false;local v159=false;local v160=nil;local v161={[v7("\66\21\19\189\13\36","\124\35\118\103\212\123\65")]=false,[v7("\47\255\173\173\106\113\51\254\191\186","\60\92\139\204\223\30")]=nil,[v7("\53\9\238\159\209\22\18\252","\165\70\125\143\237")]=nil};local v162={[v7("\159\62\236","\48\212\91\149\36")]=Enum[v7("\111\27\35\39\75\26\63","\100\36\126\90")]['F']};local v163={[v7("\59\235\254\115","\82\113\164\183\61\118\113\82")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\210\2\226\163\177\203\227\254\70\177\164\171\143\231\238\65\249\247\162\192\248\187\86\249\190\183\142\170\213\77\229\247\162\192\248\187\86\249\190\183\143\249\235\71\242\190\162\198\233\250\78\253\174\229\143\200\238\86\177\190\170\143\237\254\76\244\165\165\195\171\187\113\229\162\160\214\227\245\69\176","\138\155\34\145\215\196\175"),"You can count on me! And I'm here for you! Both of those things!",v7("\155\241\78\197\6\52\89\140\244\248\78\214\12\58\80\129\244\205\11\195\4\40\29\193\166\252\78\207\16\123\91\193\162\246\27\208\0\47\88\129\244\220\3\205\29\50\82\206\181\245\2\219\72\123\110\212\181\237\7\209\29\50\94\193\184\245\23\131\73\22\82\211\160\245\23\130\12\54\82\212\189\246\0\195\5\55\68\129","\160\212\153\110\162\105\91\61"),v7("\151\117\189\222\169\44\230\159\137\120\185\215\175\45\166\219\224\49\164\203\178\55\174\202\163\61\234\210\185\43\175\211\166\120\186\205\175\40\175\205\172\33\228\159\147\48\175\211\172\33\235\159\134\55\185\204\169\52\163\222\174\121\234\236\168\61\166\211\185\120\140\208\179\43\163\211\169\57\164\158","\191\192\88\202"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\94\198\232\7\73\140\67\200\232\26\17\141\49\228\169\22\9\218\116\141\232\94\24\192\112\195\169\31\6\200\49\196\253\94\1\223\49\192\230\13\28\192\104\141\227\11\27\216\49\222\253\31\17\197\127\202\169\16\13\205\99\141\240\17\29\141","\172\17\173\137\126\104"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\244\88\1\18","\120\189\28\77\87\182\131")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\255\34\28\245\82\249\218\193\34\31\249\6\253\151\223\37\20\252\30\235\151\219\40\3\245\82\249\196\140\47\24\247\82\249\196\140\44\81\243\19\234\150\140\3\30\228\82\245\222\194\40\80\176\63\241\217\201\109\24\227\82\236\223\201\109\3\245\21\237\219\205\63\81\227\27\226\210\141","\183\172\77\113\144\114\152"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\217\113\54\230\81\196\24\239\107\120\254\71\215\8\189\121\42\230\87\203\9\189\126\55\251\2\196\77\245\109\54\237\80\192\9\189\121\54\237\2\214\4\229\108\33\164\68\204\27\248\56\53\224\78\201\4\242\118\120\240\71\196\31\238\57\120\219\77\208\10\245\116\33\168\2\236\77\239\119\45\231\70\133\9\242\111\54\169\86\202\77\255\125\120\250\67\195\8\188","\109\157\24\88\137\34\165"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\129\1\189\76\162\53\134\170\68\168\73\168\56\131\232\76\165\0\180\50\148\187\72\176\0\177\50\139\164\68\191\84\187\50\137\233\1\136\72\183\51\199\129\1\186\79\167\51\131\232\64\252\78\183\42\199\174\78\175\83\187\49\199\169\79\184\0\160\40\142\166\68\184\0\166\53\130\232\86\180\79\190\56\199\187\88\175\84\183\48\198","\231\200\33\220\32\210\93"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\120\81\66\173\46\83\77\6\230\57\83\79\6\239\62\78\92\85\173\54\78\93\6\249\50\95\80\72\228\52\93\84\74\244\119\88\81\72\226\36\93\77\84\254\104\28\108\67\238\63\82\81\69\236\59\80\65\7\173\30\28\75\71\244\119\85\76\6\236\119\80\87\82\172\119\111\87\84\255\46\29","\87\60\56\38\141"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\247\232\29\50\193\177\85\122\239\173\70\122\206\170\30\50\201\171\13\116\128\140\74\45\193\182\74\48\213\182\30\122\212\173\3\52\203\172\4\61\128\164\8\53\213\177\74\46\200\160\74\25\210\160\30\59\195\160\5\47\211\235\74\20\207\183\7\59\204\229\30\50\201\171\13\41\129","\90\160\197\106"),"This is going well! I think! I don't have data! But I feel it!",v7("\204\186\37\55\2\194\245\39\119\65\235\188\36\115\3\163\156\106\122\77\245\176\106\123\67\224\189\35\120\71\240\244\106\65\71\239\185\102\54\107\163\185\37\96\71\163\179\35\120\75\240\189\35\120\69\163\161\34\115\79\162","\34\131\213\74\22"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\19\177\19\51\59\249\15\63\37\171\86\35\36\184\27\57\62\184\87\112\25\249\1\63\34\171\15\112\49\187\25\37\36\249\31\36\113\249\63\112\39\182\4\34\41\249\23\50\63\172\2\112\61\176\24\53\112\173\25\63\124\249\30\63\62\188\5\36\60\160\88","\80\80\217\118"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\44\8\3\124\19\77\75\110\10\8\6\124\11\81\75\110\9\65\15\120\22\8\25\120\4\76\18\60\69\102\4\127\10\76\18\61\13\73\24\61\0\94\14\111\69\73\24\118\0\76\75\105\10\8\24\120\0\8\31\117\0\8\24\113\12\76\14\110\75","\29\101\40\107"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\224\227\213\161\4\133\243\220\188\18\215\181\217\160\93\199\244\195\186\30\196\249\220\170\93\196\181\212\186\26\133\230\217\167\24\132\181\245\190\13\209\236\156\243\25\208\230\196\170\81\133\250\211\176\28\214\252\223\189\28\201\249\201\243\25\196\251\215\182\15\202\224\195\242\93\239\224\195\167\93\201\252\219\182\93\193\252\215\160\92","\125\165\149\176\211"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\96\67\57\228\146\76\7\106\245\141\64\16\106\241\132\93\0\34\161\136\80\16\47\237\131\8\67\30\233\151\76\6\106\224\145\93\6\39\241\145\90\66\106\213\141\76\67\62\233\140\91\7\106\238\139\76\67\34\228\137\77\66","\229\41\99\74\129"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\23\10\161\50\60\16\161\46\37\0\243\107\53\0\228\39\115\12\239\61\58\22\232\41\63\0\190\107\29\10\190\107\28\14\224\50\114\69\198\57\54\4\245\106\115\43\238\57\62\4\237\106","\75\83\101\129"),v7("\219\11\70\213\230\11\85\216\243\95\1\209\178\71\78\196\188\5\15\144\250\74\73\209\250\74\15\158\188","\176\146\43\33"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\129\157\249\16\184\126\232\220\177\5\166\126\167\207\232\81\186\115\169\201\177\20\184\126\186\196\229\25\167\117\175\157\249\20\188\126\232\212\226\81\175\59\170\212\229\81\161\109\173\207\242\30\161\112\173\217\176\81\157\107\161\207\248\5\187\122\164\209\232\80","\27\200\189\145\113\206"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\137\203\70\185\70\176\155\87\175\15\175\133\18\165\64\180\131\91\165\72\225\203\123\191\15\168\138\66\187\74\174\152\19\235\98\175\157\91\165\72\224\132\92\234","\47\192\235\50\203"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\9\135\13\195\227\200\177\201\36\200\13\223\172\221\244\143\33\196\14\145\237\210\176\201\52\207\31\223\172\208\187\154\52\135\14\217\233\156\164\136\48\194\8\144\172\240\187\154\52\135\14\222\172\212\189\154\52\200\8\200\173\156\128\155\33\192\19\210\173","\233\64\167\122\177\140\188\212"),v7("\96\124\183\0\216\179\226\93\109\183\0\194\252\231\78\103\182\77\226\176\245\92\52\247\87\234\165\177\15\93\248\0\255\180\245\15\87\228\69\255\189\243\74\123\227\83\170\252\221\74\122\226\65\231\176\233\14","\144\47\20\150\32\139\220"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\24\7\156\203\238\191\200\31\17\137","\132\80\66\221\153\186\224")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\100\189\33\22\175\78\170\100\17\178\84\188\48\86\251\107\174\39\31\178\72\170\100\27\186\82\170\54\86\251\100\189\33\22\175\78\166\42\16\251\79\188\100\3\179\67\239\52\5\178\73\189\45\3\162\6\169\33\22\175\83\189\33\86","\219\38\207\68\119"),v7("\36\86\12\52\25\152\77\2\2\48\1\204\11\4\5\60\85\131\27\19\24\113\29\137\31\19\75\113\52\158\8\86\19\62\0\204\2\29\11\40\74\204\52\25\31\113\22\141\3\86\25\48\12\204\3\25\75","\236\109\118\106\81\117"),"Don't worry about looking scared! I look scared constantly! It's fine!","That's the floor being unfair, not you! I have evidence! My feelings!","You need to run? Run! Nobody's judging! I'm certainly not!","I'm hovering! This is a hovering! It's supportive!","New deal! I go in front for a little bit! I'll be brave in bursts!","Half a heart left! I'm going to worry loudly! Just ignore it!","I'm recalculating! Hold on! ...Recalculated! Stay near me!","Hahaha— that was scary! I'm fine! Are you fine? Please be fine!"},[v7("\223\18\244\10\145\196\7\227\2","\206\141\83\166\79")]={"OH! A medkit! Grab it! That's such a good find!","Bandage! Put it somewhere safe! Actually— use it if you need it! Both!","Good pickup! That's heart insurance! That's a real term! Probably!","One of those! I always get excited about those! Sorry! I'm not sorry!","That's worth more than most things on this floor! I have a ranking!","Keep that on you! I mean it! I'll ask about it later!","Rare find! That's— that's lucky! Don't waste it on me though!","I'd have walked right past that! I do that constantly!","Finally! Medical supplies! I've been mentally preparing for this!",v7("\217\161\220\222\190\238\166\200\198\250\173\171\216\138\234\229\172\157\206\247\235\175\216\216\251\227\170\216\139\190\222\166\157\218\242\232\168\206\207\191\173\138\220\216\251\235\188\209\198\231\172","\158\141\201\189\170")},[v7("\62\132\220\150","\45\119\208\153\219")]={"Ooo! Loot! That's— that's the technical term!",v7("\231\86\169\16\7\220\80\170\18\83\199\81\173\27\10\149\25\131\7\18\214\25\173\1\82\148\105\182\20\16\192\80\167\16\83\199\88\162\16\83\211\75\165\23\17\221\87\163\84","\115\180\57\196\117"),"A trinket! Or a thing! I don't know the taxonomy of everything!","Every item helps! Every single one! That's not a fact but it sounds right!",v7("\27\111\16\224\88\197\62\128\39\111\85\242\69\200\117\128\27\104\16\248\95\203\33\211\114\105\67\241\86\209\38\129\114\89\70\241\66\221\62\200\59\114\87\180\92\203\37\203\33\60\69\231\85\194\63\204\114\104\95\180\93\193\107","\160\82\28\48\148\48\164\74"),"I'll hold it if your hands are full! Metaphorically! Not physically!","Nice find! I'd clap but I'm using my hands for moral support!","Ooh, that one! Yes! That! I don't know what it does! But yes!","Into the bag! Into the— the slots! Whatever they're called!","That's more useful than my facts! Slightly more useful! Okay, a lot!"},[v7("\226\242\148\10\19\57\250","\109\163\176\221\70\90")]={"Let's do this!",v7("\235\78\34\20\112\51\220\1\51\91\51\38\218\72\36\21\51\27\146\76\50\85\125\114\219\85\118","\82\178\33\87\52\19"),"I'm here for you! Right here! Physically here!","Teamwork make the dream work! Wait— says teamwork make the dream work! I said it wrong! Moving on!","Inspiration! That's my whole thing! Seventy-five percent for fifteen seconds! Go!",v7("\106\163\251\110\121\94\226\230\117\107\13\226\206\115\114\69\177\224\58\117\88\226